const raw = $input.first().json.output ?? $input.first().json.text ?? '';
let o={};try{const m=String(raw).match(/\{[\s\S]*\}/);o=JSON.parse(m?m[0]:raw);}catch(e){o={};}
const now=new Date();
function fut(d,mo,y){d=parseInt(d);mo=parseInt(mo);if(!d||!mo)return '';let year=y?parseInt(y):now.getFullYear();if(!y){const t=new Date(now.getFullYear(),now.getMonth(),now.getDate());if(new Date(year,mo-1,d)<t)year+=1;}return String(d).padStart(2,'0')+'/'+String(mo).padStart(2,'0')+'/'+year;}
function hh(h){if(!h)return '';h=String(h).trim();if(/^[0-9]{1,2}$/.test(h))return h.padStart(2,'0')+':00';const m=h.match(/^([0-9]{1,2}):([0-9]{2})/);return m?m[1].padStart(2,'0')+':'+m[2]:h;}
return [{ json: {
  intent:o.intent||'FUERA_DE_ALCANCE', nombre:o.nombre||'', motivo:o.motivo||'',
  fecha:fut(o.dia,o.mes,o.anio), hora:hh(o.hora),
  fecha_ref:fut(o.dia_ref,o.mes_ref,o.anio_ref), hora_ref:hh(o.hora_ref)
} }];

const req=$('Contrato de datos').first().json;
const now=new Date();const today=new Date(now.getFullYear(),now.getMonth(),now.getDate());
function parseF(f){f=String(f||'').trim();let m=f.match(/^([0-9]{1,2})\/([0-9]{1,2})\/([0-9]{4})$/);if(m)return new Date(+m[3],+m[2]-1,+m[1]);m=f.match(/^([0-9]{4})-([0-9]{1,2})-([0-9]{1,2})$/);if(m)return new Date(+m[1],+m[2]-1,+m[3]);const d=new Date(f);return isNaN(d)?null:new Date(d.getFullYear(),d.getMonth(),d.getDate());}
function sameF(a,b){const x=parseF(a),y=parseF(b);return !!(x&&y&&x.getTime()===y.getTime());}
const n=s=>String(s??'').trim().toLowerCase();
const rows=$input.all().map(i=>i.json).filter(r=>r&&r.Nombre);
const mine=rows.filter(r=>n(r.Nombre)===n(req.nombre) && (function(){const d=parseF(r.Fecha);return d&&d>=today;})());
let target=null;
if(req.motivo) target=mine.find(r=>n(r.Motivo)===n(req.motivo));
if(!target&&req.fecha_ref&&req.hora_ref) target=mine.find(r=>sameF(r.Fecha,req.fecha_ref)&&n(r.Hora)===n(req.hora_ref));
if(!target&&req.fecha_ref&&!req.hora_ref) target=mine.find(r=>sameF(r.Fecha,req.fecha_ref));
let out; const falta=[];
if(!req.nombre) falta.push('nombre');
if(target){
  const nf=req.fecha||target.Fecha, nh=req.hora||target.Hora;
  if(!req.fecha && !req.hora) falta.push('la nueva fecha u hora');
  if(falta.length){ out={accion:'faltan_datos',mensaje:'Para modificar el turno faltan datos: '+falta.join(', ')+'.'}; }
  else { const choque=mine.find(r=>r.ID!==target.ID&&sameF(r.Fecha,nf)&&n(r.Hora)===n(nh));
    if(choque) out={accion:'rechazo',mensaje:'Ya tenes un turno el '+nf+' a las '+nh+'.'};
    else out={accion:'modificar',id:target.ID,nombre:req.nombre,motivo:target.Motivo,fecha:nf,hora:nh}; }
}else{
  if(!req.fecha) falta.push('fecha');
  if(!req.hora) falta.push('hora');
  if(!req.motivo) falta.push('motivo');
  if(falta.length){ out={accion:'faltan_datos',mensaje:'No se puede agendar la cita: faltan datos obligatorios ('+falta.join(', ')+').'}; }
  else if(req.motivo&&mine.find(r=>n(r.Motivo)===n(req.motivo))) out={accion:'rechazo',mensaje:'Ya tenes un turno para el motivo "'+req.motivo+'".'};
  else if(mine.find(r=>sameF(r.Fecha,req.fecha)&&n(r.Hora)===n(req.hora))) out={accion:'rechazo',mensaje:'Ya tenes un turno el '+req.fecha+' a las '+req.hora+'.'};
  else out={accion:'crear',nombre:req.nombre,motivo:req.motivo,fecha:req.fecha,hora:req.hora};
}
return [{ json: out }];

