const rec = $('Buscar memoria (Airtable)').first().json || {};
const f = rec.fields || {};
const chat = $('When chat message received').first().json || {};
const nuevo = !rec.id;
return [{ json: {
  session_id: nuevo ? (chat.sessionId || '') : (f['Session_ID'] || chat.sessionId),
  es_nuevo: nuevo,
  estado: nuevo ? 'En Progreso' : (f['Estado del Caso'] || ''),
  last_summary: nuevo ? '' : (f['Resumen Consolidado'] || ''),
  datos_clave: nuevo ? '' : (f['Datos Clave'] || ''),
  mensajes: Number(f['Mensajes'] || 0) + 1
} }];

const raw = $json.output || '';
let o={}; try{ const m=String(raw).match(/\{[\s\S]*\}/); o=JSON.parse(m?m[0]:raw); }catch(e){ o={}; }
const cons = $('Consolidar datos').first().json || {};
const accion = o.accion_requerida || '';
return [{ json: {
  session_id: cons.session_id,
  resumen: o.asunto_principal || cons.last_summary || '',
  datos_clave: cons.datos_clave + (accion ? (' | Accion: ' + accion) : ''),
  estado: cons.estado,
  mensajes: cons.mensajes
} }];

const ctx = $('Preparar contexto').first().json || {};
const c = $('Contrato de datos').first().json || {};
function field(s,key){ const parts=String(s||'').split('|'); for (const p of parts){ const t=p.trim(); if (t.toLowerCase().indexOf(key.toLowerCase()+':')===0) return t.slice(key.length+1).trim(); } return ''; }
const prev = ctx.datos_clave || '';
const nombre=(c.nombre||'').trim(), motivo=(c.motivo||'').trim(), turno=((c.fecha||'')+' '+(c.hora||'')).trim();
const paciente = nombre || field(prev,'Paciente');
const mot = motivo || field(prev,'Motivo');
const tur = turno || field(prev,'Turno');
const datos_clave = 'Paciente: ' + paciente + ' | Motivo: ' + mot + ' | Turno: ' + tur;
return [{ json: { session_id: ctx.session_id, mensajes: ctx.mensajes, last_summary: ctx.last_summary, datos_clave: datos_clave, estado: ctx.estado || 'En Progreso' } }];

